def parse(text):
    tickets = []
    for entry in text.split(","):
        identity, sep, rest = entry.partition(":")
        identity = identity.strip()
        if not identity or not sep:
            raise ValueError("expected id:dependencies")
        dependencies = tuple(d.strip() for d in rest.split("+")) if rest.strip() else ()
        if any(not dependency for dependency in dependencies):
            raise ValueError("empty dependency ID")
        tickets.append(Ticket(identity, dependencies))
    by_id = {t.id: t for t in tickets}
    if len(by_id) != len(tickets):
        raise ValueError("duplicate ID")
    visiting, done = set(), set()
    for ticket in tickets:
        stack = [(ticket.id, False)]
        while stack:
            identity, leaving = stack.pop()
            if leaving:
                visiting.remove(identity)
                done.add(identity)
                continue
            if identity not in by_id:
                raise ValueError("unknown dependency")
            if identity in visiting:
                raise ValueError("cycle")
            if identity in done:
                continue
            visiting.add(identity)
            stack.append((identity, True))
            stack.extend((dependency, False)
                         for dependency in reversed(by_id[identity].dependencies))
    return tuple(tickets)

class Attempt:
    def __init__(self, identity, ticket):
        self.record = {"id": identity, "status": "running", "revision": None}
        self.ticket = ticket

    def submit(self, revision):
        if self.record["status"] != "running":
            raise ValueError("not running")
        self.record["revision"] = revision
        self.record["status"] = "submitted"
        self.ticket["attempt"] = self.record["id"]
        self.ticket["revision"] = revision
        self.ticket["status"] = "submitted"

import math
import os
from pathlib import Path
import subprocess
import tempfile

def atomic_write(destination, text):
    destination = Path(destination)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8",
                                         dir=destination.parent, delete=False) as file:
            temporary = Path(file.name)
            file.write(text)
        os.replace(temporary, destination)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)

def invoke(argv, cwd, timeout):
    try:
        finite = math.isfinite(timeout)
    except (TypeError, ValueError, OverflowError):
        finite = False
    if not finite:
        raise ValueError("finite timeout required")
    return subprocess.run(argv, cwd=cwd, capture_output=True, text=True,
                          timeout=timeout, check=False)

