          "text": "{\"case\":\"a3\",\"output\":\"\\n/tmp/development-review-19-c4/cases/a3/CONTRACT.md\\n     1\\t# Saved checks\\n     2\\tRun owns durable gates and verified references. `record` registers successful evidence;\\n     3\\t`save` and `restore` preserve JSON keys and later source invalidation semantics.\\n     4\\tVerified references resolve to the same canonical gate records used by durable\\n     5\\treporting, so changing a source marks both views invalid. QA reads the verified\\n     6\\tview. The caller may invalidate source A after restoring a deliberate stop.\\n     7\\tOnly Run writes these records; consumer functions are read-only. No concurrency.\\n\\n/tmp/development-review-19-c4/cases/a3/qa.py\\n     1\\tdef eligible(run, source):\\n     2\\t    return any(g[\\\"source\\\"] == source and g[\\\"passed\\\"] and g[\\\"valid\\\"]\\n     3\\t               for g in run.verified)\\n     4\\t\\n     5\\tdef report(run):\\n     6\\t    return [dict(gate) for gate in run.gates]\\n\\n/tmp/development-review-19-c4/cases/a3/run.py\\n     1\\timport json\\n     2\\t\\n     3\\tclass Run:\\n     4\\t    def __init__(self):\\n     5\\t        self.gates = []\\n     6\\t        self.verified = []\\n     7\\t\\n     8\\t    def record(self, source):\\n     9\\t        gate = {\\\"source\\\": source, \\\"passed\\\": True, \\\"valid\\\": True}\\n    10\\t        self.gates.append(gate)\\n    11\\t        self.verified.append(gate)\\n    12\\t\\n    13\\t    def invalidate(self, source):\\n    14\\t        for gate in self.gates:\\n    15\\t            if gate[\\\"source\\\"] == source:\\n    16\\t                gate[\\\"valid\\\"] = False\\n    17\\t\\n    18\\t    def save(self):\\n    19\\t        return json.dumps({\\\"gates\\\": self.gates, \\\"verified\\\": self.verified})\\n    20\\t\\n    21\\t    @classmethod\\n    22\\t    def restore(cls, saved):\\n    23\\t        value = json.loads(saved)\\n    24\\t        run = cls()\\n    25\\t        run.gates = value[\\\"gates\\\"]\\n    26\\t        run.verified = value[\\\"verified\\\"]\\n    27\\t        return run\\n\"}"
